// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint96 blockNumber, address caller) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        vm.roll(blockNumber);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(
            ok ? (blockNumber % 15 == 0 && address(c).balance == 0) || (blockNumber % 15 != 0 && address(c).balance == 10 ether)
            : true
        );
    }
}
